function generateLineupsData(n,t){t.preventDefault();var i=$("#generateLineupsData").serialize();console.log(i);$.ajax({type:"POST",url:urlPrefix()+"/Match/Lineups?matchId="+n+"&"+i,contentType:"application/json; charset=utf-8",success:function(t){$("#btnApplyLineups").on("click",function(){console.log("ASdasdads");applyLineups(n,t)});$("#lineupsRequestContent").text("");jsonView.format(t,"#lineupsRequestContent");$("#lineupsRequest").modal()},error:function(){console.log("failed")}})}function applyLineups(n,t){$.ajax({type:"POST",url:urlPrefix()+"/Match/Lineups/"+n,contentType:"application/json; charset=utf-8",dataType:"json",data:JSON.stringify(t),success:function(){console.log("success")},error:function(){console.log("failed")}})}function getMatchLineups(n,t){t.preventDefault();$.ajax({type:"GET",url:urlPrefix()+"/Match/Lineups/"+n,contentType:"application/json; charset=utf-8",success:function(n){$("#lineupsDataContent").text("");document.getElementById("lineupsImage").innerHTML=n.pitchView;n.pitchView=null;jsonView.format(n,"#lineupsDataContent");$("#lineupsData").modal()},error:function(){$("#lineupsDataContent").text("No Data");$("#lineupsData").modal()}})}function generateH2HData(n,t){t.preventDefault();console.log(n);var i=$("#generateH2HData").serialize();$.ajax({type:"POST",url:urlPrefix()+"/Team/H2H/Generate?matchId="+n+"&"+i,contentType:"application/json; charset=utf-8",success:function(t){$("#btnApplyH2H").on("click",function(){applyH2H(n,t)});$("#H2HRequestContent").text("");jsonView.format(t,"#H2HRequestContent");$("#h2hRequest").modal()},error:function(){console.log("failed")}})}function applyH2H(n,t){$.ajax({type:"POST",url:urlPrefix()+"/Team/H2H/Apply/"+n,contentType:"application/json; charset=utf-8",dataType:"json",data:JSON.stringify(t),success:function(){console.log("success")},error:function(){console.log("failed")}})}function getMatchH2H(n,t){t.preventDefault();$.ajax({type:"GET",url:urlPrefix()+"/Team/H2H/"+n,contentType:"application/json; charset=utf-8",success:function(n){$("#h2hDataContent").text("");jsonView.format(n,"#h2hDataContent");$("#h2hData").modal()},error:function(){$("#h2hDataContent").text("No Data");$("#h2hData").modal()}})}function generateTeamResultData(n,t){t.preventDefault();var i=$("#generateTeamResultData").serialize();$.ajax({type:"POST",url:urlPrefix()+"/Team/Results/Generate?matchId="+n+"&"+i,contentType:"application/json; charset=utf-8",success:function(t){$("#btnApplyH2H").on("click",function(){applyTeamResult(n,t)});$("#H2HRequestContent").text("");jsonView.format(t,"#H2HRequestContent");$("#h2hRequest").modal()},error:function(){console.log("generate team result failed")}})}function applyTeamResult(n,t){$.ajax({type:"POST",url:urlPrefix()+"/Team/Results/Apply/"+n,contentType:"application/json; charset=utf-8",dataType:"json",data:JSON.stringify(t),success:function(){console.log("success")},error:function(){console.log("apply team result failed")}})}function getRootUrl(){return window.location.origin?window.location.origin+"/":window.location.protocol+"/"+window.location.host+"/"}function urlPrefix(){return getRootUrl()+$("#urlPrefix").val()}